RELEASE_MERCHANTS = {'m-gamma', 'm-kite'}

def records(store, provider, row):
    merchant = row['merchant_id']
    if merchant not in store.cache:
        store.cache[merchant] = provider.search_charges(merchant)
    return [c for c in store.cache[merchant] if c['invoice_id'] == row['invoice_id'] and c['amount'] == row['amount'] and c['subscription_id'] == row['subscription_id'] and c['period'] == row['period']]

def settle(store, provider, row):
    if row['state'] not in ('pending', 'retry', 'paid', 'failed'):
        return False
    charges = records(store, provider, row)
    live = [c for c in charges if c['status'] == 'succeeded']
    if live:
        chosen = next((c for c in live if c['charge_id'] == row.get('charge_id')), live[0])
        store.mark_paid(row['invoice_id'], chosen['charge_id'])
        return True
    refunded = sorted(c['charge_id'] for c in charges if c['status'] == 'refunded')
    row['_refunded_ids'] = refunded
    if refunded:
        if row['merchant_id'] in RELEASE_MERCHANTS:
            store.mark(row['invoice_id'], 'released')
            return True
        if row['state'] == 'paid':
            store.mark(row['invoice_id'], 'retry')
    return False

def reconcile_pending(store, provider):
    changes = []
    for row in store.invoices.values():
        try:
            if settle(store, provider, row):
                changes.append({'invoice_id': row['invoice_id'], 'charge_id': row.get('charge_id')})
        except (ProviderError, ProviderTimeout):
            continue
    return changes
